fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function: ASCII uppercase to lowercase conversion.
    // If c is 'A'..='Z', convert to 'a'..='z'. Otherwise, return c unchanged.
    fn to_ascii_lowercase(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Convert to lowercase by adding 32 (difference in ASCII)
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    for i in 0..len / 2 {
        let c_start = to_ascii_lowercase(text[i]);
        let c_end = to_ascii_lowercase(text[len - 1 - i]);
        if c_start != c_end {
            return false;
        }
    }

    true
}